create table public.knowledge_categories(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,name text not null check(length(trim(name)) between 2 and 100),audience text not null default 'INTERNAL' check(audience in('INTERNAL','EXTERNAL','BOTH')),active boolean not null default true,created_at timestamptz not null default now(),created_by uuid references public.user_profiles(id) on delete set null,unique(organization_id,name));
create table public.knowledge_articles(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,category_id uuid not null references public.knowledge_categories(id) on delete restrict,title text not null check(length(trim(title)) between 5 and 240),slug text not null check(slug ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'),summary text not null check(length(trim(summary)) between 10 and 1000),audience text not null check(audience in('INTERNAL','EXTERNAL','BOTH')),status text not null default 'DRAFT' check(status in('DRAFT','IN_REVIEW','PENDING_APPROVAL','PUBLISHED','OBSOLETE','ARCHIVED')),current_version integer not null default 1 check(current_version>0),owner_id uuid references public.user_profiles(id) on delete set null,created_at timestamptz not null default now(),created_by uuid not null references public.user_profiles(id) on delete restrict,updated_at timestamptz not null default now(),unique(organization_id,slug));
create table public.knowledge_article_versions(id uuid primary key default gen_random_uuid(),article_id uuid not null references public.knowledge_articles(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,version_number integer not null check(version_number>0),content text not null check(length(trim(content)) between 10 and 50000),change_reason text not null check(length(trim(change_reason)) between 5 and 1000),created_at timestamptz not null default now(),created_by uuid not null references public.user_profiles(id) on delete restrict,unique(article_id,version_number));
create trigger knowledge_articles_updated before update on public.knowledge_articles for each row execute function public.set_updated_at();
create index knowledge_articles_search_idx on public.knowledge_articles(organization_id,status,audience,updated_at desc);
alter table public.knowledge_categories enable row level security; alter table public.knowledge_articles enable row level security; alter table public.knowledge_article_versions enable row level security;
create policy "members read knowledge categories" on public.knowledge_categories for select to authenticated using(public.is_organization_member(organization_id));
create policy "members read draft knowledge" on public.knowledge_articles for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','AUDITOR']::public.platform_role[]));
create policy "members read knowledge versions" on public.knowledge_article_versions for select to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','AUDITOR']::public.platform_role[]));
create or replace function public.create_knowledge_article(target_organization_id uuid,target_category_id uuid,target_title text,target_slug text,target_summary text,target_content text,target_audience text,target_change_reason text) returns uuid language plpgsql security definer set search_path=public as $$ declare article_id uuid;
begin if not public.has_organization_role(target_organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'KNOWLEDGE_NOT_AUTHORIZED'; end if; if not exists(select 1 from public.knowledge_categories where id=target_category_id and organization_id=target_organization_id and active) then raise exception 'KNOWLEDGE_CATEGORY_INVALID'; end if; if length(trim(target_title)) not between 5 and 240 or trim(target_slug) !~ '^[a-z0-9]+(?:-[a-z0-9]+)*$' or length(trim(target_summary)) not between 10 and 1000 or length(trim(target_content)) not between 10 and 50000 or length(trim(target_change_reason)) not between 5 and 1000 or target_audience not in('INTERNAL','EXTERNAL','BOTH') then raise exception 'KNOWLEDGE_INVALID_INPUT'; end if; insert into public.knowledge_articles(organization_id,category_id,title,slug,summary,audience,owner_id,created_by) values(target_organization_id,target_category_id,trim(target_title),trim(target_slug),trim(target_summary),target_audience,auth.uid(),auth.uid()) returning id into article_id; insert into public.knowledge_article_versions(article_id,organization_id,version_number,content,change_reason,created_by) values(article_id,target_organization_id,1,trim(target_content),trim(target_change_reason),auth.uid()); insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(target_organization_id,auth.uid(),'KNOWLEDGE_ARTICLE_CREATED','knowledge_article',article_id,jsonb_build_object('version',1,'audience',target_audience),'WEB'); return article_id; end; $$;
revoke all on function public.create_knowledge_article(uuid,uuid,text,text,text,text,text,text) from public; grant execute on function public.create_knowledge_article(uuid,uuid,text,text,text,text,text,text) to authenticated;
create or replace function public.create_knowledge_category(target_organization_id uuid,target_name text,target_audience text) returns uuid language plpgsql security definer set search_path=public as $$ declare category_id uuid; begin if not public.has_organization_role(target_organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'KNOWLEDGE_NOT_AUTHORIZED'; end if; if length(trim(target_name)) not between 2 and 100 or target_audience not in('INTERNAL','EXTERNAL','BOTH') then raise exception 'KNOWLEDGE_CATEGORY_INVALID'; end if; insert into public.knowledge_categories(organization_id,name,audience,created_by) values(target_organization_id,trim(target_name),target_audience,auth.uid()) returning id into category_id; insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,source) values(target_organization_id,auth.uid(),'KNOWLEDGE_CATEGORY_CREATED','knowledge_category',category_id,'WEB'); return category_id; end; $$;
revoke all on function public.create_knowledge_category(uuid,text,text) from public; grant execute on function public.create_knowledge_category(uuid,text,text) to authenticated;
